/** Finder contracts are generated from Core alongside the persistence protocol. */
export type {
  FinderCourse,
  FinderRow,
  Condition,
  Factor,
  Suggestion,
  RemotePlan,
  RemoteQuery,
} from "../generated/persistence";
import type {
  Condition,
  FinderContext as CoreFinderContext,
} from "../generated/persistence";
export type ConditionType = Condition["type"];
// UI callers use a Map; the transport representation is generated by Core.
export type FinderContext = Omit<CoreFinderContext, "recommended"> & {
  recommended: Map<string, CoreFinderContext["recommended"][string]>;
};
export const DAYS = ["月", "火", "水", "木", "金", "土"] as const;
export const LOCAL_TYPES = new Set<ConditionType>(["free"]);
